import sys
src, dst = sys.argv[1], sys.argv[2]
t = open(src, encoding='utf-8').read()

def rep(old, new):
    global t
    n = t.count(old)
    assert n == 1, (n, old[:90])
    t = t.replace(old, new)

def insert_after_line_starting(prefix, block):
    global t
    L = t.split('\n')
    idx = [i for i, s in enumerate(L) if s.startswith(prefix)]
    assert len(idx) == 1, (prefix, idx)
    L.insert(idx[0] + 1, block)
    t = '\n'.join(L)

